{
  "version": 1,
  "violations": []
}

/**
 * Create Repository Development Sub-tasks
 *
 * Reads the {code:json|title=affected_repos} block from a story-solution (SA)
 * ticket description and creates one development Sub-task per repository under
 * the same parent as the SA ticket.
 *
 * Summary format:   [repo] [parent summary]
 * Description:      Your scope only development for [repo] based on solution in
 *                   [SA link] and parent acceptance criteria [parent link]
 *
 * Duplicate-safe: skips repos that already have a matching Sub-task under the parent.
 *
 * gh-1004: action was one 200+ line function (CRAP 180.9). The pure decisions
 * and payload builders are extracted below so action only orchestrates; every
 * helper is covered directly by js/unit-tests/test_createRepoTasks.js.
 */

var configModule = require('./config.js');
var trackersModule = require('./common/trackers.js');
var linkedIssuesReport = require('./common/linkedIssuesReport.js');
var configLoader = null;
try { configLoader = require('./configLoader.js'); } catch (e) {}
var truncateSummary = configModule.truncateSummary;
var JIRA_SUMMARY_MAX_LENGTH = configModule.JIRA_SUMMARY_MAX_LENGTH;

function resolveProjectConfig(params) {
    return configLoader ? configLoader.loadProjectConfig(params) : null;
}

function getJiraBaseUrl() {
    try {
        var url = java.lang.System.getenv('JIRA_BASE_PATH');
        return url ? url.replace(/\/$/, '') : '';
    } catch (e) {
        return '';
    }
}

function jiraLink(key, baseUrl) {
    return '[' + key + '|' + baseUrl + '/browse/' + key + ']';
}

function parseAffectedRepos(description) {
    if (!description) return [];
    var startMarker = '{code:json|title=affected_repos}';
    var endMarker = '{code}';
    var startIdx = description.indexOf(startMarker);
    if (startIdx === -1) {
        console.warn('No {code:json|title=affected_repos} block found in description');
        return [];
    }
    var jsonStart = startIdx + startMarker.length;
    var endIdx = description.indexOf(endMarker, jsonStart);
    if (endIdx === -1) {
        console.warn('Closing {code} not found after affected_repos block');
        return [];
    }
    var jsonStr = description.substring(jsonStart, endIdx).trim();
    try {
        var parsed = JSON.parse(jsonStr);
        return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
        console.warn('Failed to parse affected_repos JSON:', e);
        return [];
    }
}

// ---------------------------------------------------------------------------
// Pure helpers (gh-1004) — no tracker calls, unit-tested directly
// ---------------------------------------------------------------------------

function decideDuplicate(existingSummaries, repoName) {
    return existingSummaries.some(function(s) {
        return s.indexOf('[' + repoName + ']') !== -1;
    });
}

function buildRepoSummary(repoName, parentSummary) {
    // Parent summary is Jira-controlled and usually short, but a "[repo] "
    // prefix plus a long parent summary could still exceed the 255-char
    // hard limit — truncate defensively (see createRepoTasksMulti.js).
    return truncateSummary('[' + repoName + '] ' + parentSummary, JIRA_SUMMARY_MAX_LENGTH);
}

function buildScopeDescription(repoName, saKey, parentKey, baseUrl) {
    var saRef  = baseUrl ? jiraLink(saKey, baseUrl)    : saKey;
    var parRef = baseUrl ? jiraLink(parentKey, baseUrl) : parentKey;
    return 'Your scope only development for *' + repoName +
           '* based on solution in ' + saRef +
           ' and parent acceptance criteria ' + parRef;
}

function extractCreatedKey(result) {
    try {
        var parsed = typeof result === 'string' ? (/^[A-Za-z0-9_-]+$/.test(result) ? { key: result } : JSON.parse(result)) : result;
        return parsed && (parsed.key || parsed.id) ? (parsed.key || parsed.id) : null;
    } catch (e) {
        // key extraction failed — non-critical
        return null;
    }
}

function buildSummaryComment(created, skipped, baseUrl) {
    var comment = 'h3. Development Sub-tasks\n\n';
    created.forEach(function(c) {
        if (c.error) {
            comment += '* ❌ ' + c.repo + ': ' + c.error + '\n';
        } else {
            var ref = c.key && baseUrl ? jiraLink(c.key, baseUrl) : (c.key || c.summary);
            comment += '* ✅ ' + ref + ' — ' + c.repo + '\n';
        }
    });
    if (skipped.length > 0) {
        comment += '\n_Skipped (already exist): ' + skipped.join(', ') + '_\n';
    }
    return comment;
}

// ---------------------------------------------------------------------------
// Tracker-backed helpers (gh-1004) — each failure mode is non-fatal by design
// ---------------------------------------------------------------------------

function loadExistingSummaries(tracker, parentKey) {
    var existingSummaries = [];
    try {
        var provider = tracker && typeof tracker.provider === 'function' ? tracker.provider() : 'jira';
        var existing = tracker.searchIssues(
            // JQL text: provider-specific query (WIQL on ado)
            linkedIssuesReport.buildChildrenQuery(provider, parentKey, 'parent = ' + parentKey + ' AND issuetype = Sub-task', 'Sub-task'), {
            fields: ['summary']
        });
        if (Array.isArray(existing)) {
            existing.forEach(function(t) {
                var s = t.fields && t.fields.summary ? t.fields.summary : (t.summary || '');
                existingSummaries.push(s);
            });
        }
    } catch (e) {
        console.warn('Could not fetch existing Sub-tasks (will create without dedup check):', e);
    }
    return existingSummaries;
}

function createSubTasks(tracker, repos, projectKey, parentKey, parentSummary, saKey, baseUrl, ticketLabels, existingSummaries) {
    var created = [];
    var skipped = [];
    // repoName → created Jira key (for dependency linking)
    var repoKeyMap = {};

    repos.forEach(function(repo) {
        var repoName = typeof repo === 'string' ? repo : repo.name;
        if (!repoName) return;

        var summary = buildRepoSummary(repoName, parentSummary);

        // Skip if a sub-task with this repo tag already exists
        if (decideDuplicate(existingSummaries, repoName)) {
            console.log('Skipping ' + repoName + ' — sub-task already exists');
            skipped.push(repoName);
            return;
        }

        var desc = buildScopeDescription(repoName, saKey, parentKey, baseUrl);

        try {
            var result = tracker.createTicketWithParent(projectKey, 'Sub-task', summary, desc, parentKey, { labels: ticketLabels });

            var createdKey = extractCreatedKey(result);

            console.log('Created Sub-task ' + (createdKey || '(key unavailable)') + ': ' + summary);
            created.push({ repo: repoName, key: createdKey, summary: summary, depends_on: repo.depends_on || [] });
            if (createdKey) repoKeyMap[repoName] = createdKey;

        } catch (e) {
            console.error('Failed to create Sub-task for ' + repoName + ':', e);
            created.push({ repo: repoName, key: null, error: e.toString(), depends_on: [] });
        }
    });

    return { created: created, skipped: skipped, repoKeyMap: repoKeyMap };
}

function linkDependency(tracker, blockerKey, dependentKey, blocksRelationship) {
    try {
        tracker.linkIssues(blockerKey, dependentKey, blocksRelationship);
        console.log(blockerKey + ' ' + blocksRelationship + ' ' + dependentKey);
        return true;
    } catch (e) {
        console.warn('Failed to link ' + blockerKey + ' ' + blocksRelationship + ' ' + dependentKey + ':', e);
        return false;
    }
}

function moveToBlocked(tracker, key, blockedStatus) {
    try {
        tracker.moveToStatus(key, blockedStatus);
        console.log('Moved ' + key + ' to ' + blockedStatus);
    } catch (e) {
        console.warn('Failed to move ' + key + ' to ' + blockedStatus + ':', e);
    }
}

function wireDependencies(tracker, created, repoKeyMap, blocksRelationship, blockedStatus) {
    created.forEach(function(c) {
        if (!c.key || !Array.isArray(c.depends_on) || c.depends_on.length === 0) return;
        var anyLinked = false;
        c.depends_on.forEach(function(depRepo) {
            var blockerKey = repoKeyMap[depRepo];
            if (!blockerKey) {
                console.warn('Cannot resolve depends_on "' + depRepo + '" for ' + c.key + ' — skipping link');
                return;
            }
            if (linkDependency(tracker, blockerKey, c.key, blocksRelationship)) anyLinked = true;
        });
        if (anyLinked) moveToBlocked(tracker, c.key, blockedStatus);
    });
}

function postSummaryComment(tracker, saKey, comment) {
    try {
        tracker.postComment(saKey, comment);
    } catch (e) {
        console.warn('Failed to post summary comment on ' + saKey + ':', e);
    }
}

function action(params) {
    try {
        var saKey = params.ticket && params.ticket.key;
        if (!saKey) {
            return { success: false, error: 'No ticket key in params' };
        }

        console.log('createRepoTasks: processing SA ticket ' + saKey);

        // Customisable via customParams (or .dmtools/config.js jobParamPatches.createRepoTasks.customParams)
        var customParams = params.customParams || (params.jobParams && params.jobParams.customParams) || {};
        var tracker = trackersModule.createTracker(resolveProjectConfig(params), customParams);
        var blocksRelationship = customParams.blocksRelationship || 'Blocks';
        var blockedStatus      = customParams.blockedStatus      || 'Blocked';
        var ticketLabels       = customParams.labels             || ['development'];

        // Fetch the SA ticket to get description + parent
        var saTicket = tracker.getIssue(saKey, ['description', 'summary', 'parent']);
        var saFields = saTicket && saTicket.fields ? saTicket.fields : saTicket;
        var description = saFields.description ? saFields.description.toString() : '';

        // Resolve parent key
        var parentInfo = saFields.parent;
        var parentKey = parentInfo && typeof parentInfo === 'object' ? parentInfo.key : null;
        if (!parentKey) {
            return { success: false, error: 'SA ticket ' + saKey + ' has no parent ticket' };
        }
        console.log('Parent ticket: ' + parentKey);

        // Fetch parent summary
        var parentTicket = tracker.getIssue(parentKey, ['summary']);
        var parentFields = parentTicket && parentTicket.fields ? parentTicket.fields : parentTicket;
        var parentSummary = (parentFields.summary || parentKey).toString();

        // Extract repos from description
        var repos = parseAffectedRepos(description);
        if (repos.length === 0) {
            return { success: false, error: 'No affected repos found in ' + saKey + ' — ensure writeSolutionAndLabels ran first' };
        }
        console.log('Found ' + repos.length + ' affected repo(s): ' + repos.map(function(r) { return typeof r === 'string' ? r : r.name; }).join(', '));

        var baseUrl = getJiraBaseUrl();
        var projectKey = parentKey.split('-')[0];

        // Load existing Sub-tasks under the parent to avoid duplicates
        var existingSummaries = loadExistingSummaries(tracker, parentKey);

        var outcome = createSubTasks(tracker, repos, projectKey, parentKey, parentSummary, saKey, baseUrl, ticketLabels, existingSummaries);

        // Wire dependencies: blocker Blocks dependent + move dependent to Blocked status
        wireDependencies(tracker, outcome.created, outcome.repoKeyMap, blocksRelationship, blockedStatus);

        // Post summary comment on the SA ticket
        if (outcome.created.length > 0 || outcome.skipped.length > 0) {
            postSummaryComment(tracker, saKey, buildSummaryComment(outcome.created, outcome.skipped, baseUrl));
        }

        var successCount = outcome.created.filter(function(c) { return !c.error; }).length;
        return {
            success: true,
            message: 'Created ' + successCount + ' Sub-task(s) under ' + parentKey + ', skipped ' + outcome.skipped.length,
            created: successCount,
            skipped: outcome.skipped.length
        };

    } catch (error) {
        console.error('Error in createRepoTasks:', error);
        return { success: false, error: error.toString() };
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        action: action,
        parseAffectedRepos: parseAffectedRepos,
        decideDuplicate: decideDuplicate,
        buildRepoSummary: buildRepoSummary,
        buildScopeDescription: buildScopeDescription,
        extractCreatedKey: extractCreatedKey,
        buildSummaryComment: buildSummaryComment,
        loadExistingSummaries: loadExistingSummaries,
        createSubTasks: createSubTasks,
        wireDependencies: wireDependencies,
        postSummaryComment: postSummaryComment
    };
}

/**
 * Create Repository Development Sub-tasks — Multi-Task Variant
 *
 * Like createRepoTasks.js, reads the {code:json|title=affected_repos} block from
 * a story-solution (SA) ticket description and creates development Sub-tasks
 * under the same parent as the SA ticket — but supports splitting a single
 * repository's work into several independently trackable Sub-tasks via an
 * optional `tasks` array on a repo entry (see
 * instructions/story_solution/affected_repos_multi_task_split.md).
 *
 * Backward compatible: a repo entry with no `tasks` array still produces
 * exactly one Sub-task, identical to createRepoTasks.js.
 *
 * Summary format:   [repo] <task title OR repo-level reason>
 * Description:      Your scope only development for [repo] based on solution in
 *                   [SA link] and parent acceptance criteria [parent link]
 *
 * Duplicate-safe: skips (repo, title) pairs that already have a matching
 * Sub-task under the parent.
 *
 * gh-1004: action was one 200+ line function (CRAP 57.2). The pure decisions
 * and payload builders are extracted below so action only orchestrates; every
 * helper is covered directly by js/unit-tests/test_createRepoTasksMulti.js.
 */

var configModule = require('./config.js');
var trackersModule = require('./common/trackers.js');
var linkedIssuesReport = require('./common/linkedIssuesReport.js');
var configLoader = null;
try { configLoader = require('./configLoader.js'); } catch (e) {}
var truncateSummary = configModule.truncateSummary;
var JIRA_SUMMARY_MAX_LENGTH = configModule.JIRA_SUMMARY_MAX_LENGTH;

function resolveProjectConfig(params) {
    return configLoader ? configLoader.loadProjectConfig(params) : null;
}

function getJiraBaseUrl() {
    try {
        var url = java.lang.System.getenv('JIRA_BASE_PATH');
        return url ? url.replace(/\/$/, '') : '';
    } catch (e) {
        return '';
    }
}

function jiraLink(key, baseUrl) {
    return '[' + key + '|' + baseUrl + '/browse/' + key + ']';
}

function parseAffectedRepos(description) {
    if (!description) return [];
    var startMarker = '{code:json|title=affected_repos}';
    var endMarker = '{code}';
    var startIdx = description.indexOf(startMarker);
    if (startIdx === -1) {
        console.warn('No {code:json|title=affected_repos} block found in description');
        return [];
    }
    var jsonStart = startIdx + startMarker.length;
    var endIdx = description.indexOf(endMarker, jsonStart);
    if (endIdx === -1) {
        console.warn('Closing {code} not found after affected_repos block');
        return [];
    }
    var jsonStr = description.substring(jsonStart, endIdx).trim();
    try {
        var parsed = JSON.parse(jsonStr);
        return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
        console.warn('Failed to parse affected_repos JSON:', e);
        return [];
    }
}

// ---------------------------------------------------------------------------
// Flatten repo entries (with optional `tasks`) into a flat list of tasks,
// each carrying a globally-unique key "repo:id" and resolved depends_on keys.
// ---------------------------------------------------------------------------

function flattenTasks(repos) {
    var normalised = repos.map(function(r) {
        return typeof r === 'string' ? { name: r } : r;
    });

    // repoName -> array of task keys ("repo:id"), used to expand bare-repo-name deps
    var repoTaskKeys = {};
    var flat = [];

    normalised.forEach(function(repo) {
        var repoName = repo.name;
        if (!repoName) return;

        if (Array.isArray(repo.tasks) && repo.tasks.length > 0) {
            repoTaskKeys[repoName] = [];
            repo.tasks.forEach(function(t) {
                var id = t.id || t.title;
                var key = repoName + ':' + id;
                repoTaskKeys[repoName].push(key);
                flat.push({
                    key: key,
                    repo: repoName,
                    title: t.title || id,
                    reason: t.reason || '',
                    rawDependsOn: Array.isArray(t.depends_on) ? t.depends_on : [],
                    repoLevelDependsOn: Array.isArray(repo.depends_on) ? repo.depends_on : []
                });
            });
        } else {
            // Implicit single task for this repo — identical to createRepoTasks.js behaviour
            var implicitKey = repoName + ':' + repoName;
            repoTaskKeys[repoName] = [implicitKey];
            flat.push({
                key: implicitKey,
                repo: repoName,
                title: repo.reason || repoName,
                reason: repo.reason || '',
                rawDependsOn: [],
                repoLevelDependsOn: Array.isArray(repo.depends_on) ? repo.depends_on : []
            });
        }
    });

    // Resolve depends_on references into concrete task keys.
    function resolveRef(ref, ownRepo) {
        if (ref.indexOf(':') !== -1) {
            // Already a fully-qualified "repo:id" reference
            return repoTaskKeys[ref.split(':')[0]] && flat.some(function(f) { return f.key === ref; })
                ? [ref] : [];
        }
        if (repoTaskKeys[ref]) {
            // Bare repo name → depends on all of that repo's tasks
            return repoTaskKeys[ref].slice();
        }
        // Bare task id within the same repo
        var sameRepoKey = ownRepo + ':' + ref;
        return flat.some(function(f) { return f.key === sameRepoKey; }) ? [sameRepoKey] : [];
    }

    flat.forEach(function(t) {
        var resolved = {};
        t.rawDependsOn.concat(t.repoLevelDependsOn).forEach(function(ref) {
            resolveRef(ref, t.repo).forEach(function(k) {
                if (k !== t.key) resolved[k] = true;
            });
        });
        t.depends_on = Object.keys(resolved);
    });

    return flat;
}

// ---------------------------------------------------------------------------
// Topological sort over the flattened task graph
// ---------------------------------------------------------------------------

function topologicalSortTasks(tasks) {
    var byKey = {};
    tasks.forEach(function(t) { byKey[t.key] = t; });

    var sorted = [];
    var visited = {};

    function visit(key) {
        if (visited[key]) return;
        visited[key] = true;
        var t = byKey[key];
        if (t) {
            t.depends_on.forEach(function(dep) { if (byKey[dep]) visit(dep); });
            sorted.push(t);
        }
    }

    tasks.forEach(function(t) { visit(t.key); });
    return sorted;
}

// ---------------------------------------------------------------------------
// Pure helpers (gh-1004) — no tracker calls, unit-tested directly
// ---------------------------------------------------------------------------

function buildTaskPlan(repos) {
    return topologicalSortTasks(flattenTasks(repos));
}

function buildTaskSummary(repo, title) {
    // AI-authored task titles are free text and can exceed Jira's 255-char
    // summary limit (the API rejects ticket creation outright if they do) —
    // truncate defensively so a single overlong title can't sink the whole run.
    return truncateSummary('[' + repo + '] ' + title, JIRA_SUMMARY_MAX_LENGTH);
}

function buildTaskDescription(repo, reason, saKey, parentKey, baseUrl) {
    var saRef  = baseUrl ? jiraLink(saKey, baseUrl)    : saKey;
    var parRef = baseUrl ? jiraLink(parentKey, baseUrl) : parentKey;
    return (reason ? reason + '\n\n' : '') +
           'Your scope only development for *' + repo +
           '* based on solution in ' + saRef +
           ' and parent acceptance criteria ' + parRef;
}

function decideDuplicate(existingSummaries, summary) {
    return existingSummaries.indexOf(summary) !== -1;
}

function extractCreatedKey(result) {
    try {
        // tracker.createTicketWithParent already returns the extracted key
        return typeof result === 'string' ? (result || null) : (result && (result.key || result.id)) || null;
    } catch (e) {
        // key extraction failed — non-critical
        return null;
    }
}

function buildSummaryComment(created, skipped, baseUrl) {
    var comment = 'h3. Development Sub-tasks\n\n';
    created.forEach(function(c) {
        if (c.error) {
            comment += '* ❌ ' + c.summary + ': ' + c.error + '\n';
        } else {
            var ref = c.key && baseUrl ? jiraLink(c.key, baseUrl) : (c.key || c.summary);
            comment += '* ✅ ' + ref + ' — ' + c.summary + '\n';
        }
    });
    if (skipped.length > 0) {
        comment += '\n_Skipped (already exist): ' + skipped.join(', ') + '_\n';
    }
    return comment;
}

// ---------------------------------------------------------------------------
// Tracker-backed helpers (gh-1004) — each failure mode is non-fatal by design
// ---------------------------------------------------------------------------

function loadExistingSummaries(tracker, parentKey) {
    var existingSummaries = [];
    try {
        // JQL text: provider-specific query (WIQL on ado)
        var provider = tracker && typeof tracker.provider === 'function' ? tracker.provider() : 'jira';
        var existing = tracker.searchIssues(linkedIssuesReport.buildChildrenQuery(provider, parentKey, 'parent = ' + parentKey + ' AND issuetype = Sub-task', 'Sub-task'), {
            fields: ['summary']
        });
        if (Array.isArray(existing)) {
            existing.forEach(function(t) {
                var s = t.fields && t.fields.summary ? t.fields.summary : (t.summary || '');
                existingSummaries.push(s);
            });
        }
    } catch (e) {
        console.warn('Could not fetch existing Sub-tasks (will create without dedup check):', e);
    }
    return existingSummaries;
}

function createSubTasks(tracker, tasks, projectKey, parentKey, saKey, baseUrl, ticketLabels, existingSummaries) {
    var created = [];
    var skipped = [];
    // task key ("repo:id") → created Jira key, for dependency linking
    var taskKeyMap = {};

    tasks.forEach(function(t) {
        var summary = buildTaskSummary(t.repo, t.title);

        // Dedup key is "[repo] title" (not just "[repo]") so multiple tasks
        // in the same repo don't falsely collide.
        if (decideDuplicate(existingSummaries, summary)) {
            console.log('Skipping "' + summary + '" — sub-task already exists');
            skipped.push(summary);
            return;
        }

        var descBody = buildTaskDescription(t.repo, t.reason, saKey, parentKey, baseUrl);

        try {
            var result = tracker.createTicketWithParent(projectKey, 'Sub-task', summary, descBody, parentKey, { labels: ticketLabels });

            var createdKey = extractCreatedKey(result);

            console.log('Created Sub-task ' + (createdKey || '(key unavailable)') + ': ' + summary);
            created.push({ taskKey: t.key, repo: t.repo, key: createdKey, summary: summary, depends_on: t.depends_on });
            if (createdKey) taskKeyMap[t.key] = createdKey;

        } catch (e) {
            console.error('Failed to create Sub-task for ' + summary + ':', e);
            created.push({ taskKey: t.key, repo: t.repo, key: null, summary: summary, error: e.toString(), depends_on: [] });
        }
    });

    return { created: created, skipped: skipped, taskKeyMap: taskKeyMap };
}

function linkDependency(tracker, blockerKey, dependentKey, blocksRelationship) {
    try {
        tracker.linkIssues(blockerKey, dependentKey, blocksRelationship);
        console.log(blockerKey + ' ' + blocksRelationship + ' ' + dependentKey);
        return true;
    } catch (e) {
        console.warn('Failed to link ' + blockerKey + ' ' + blocksRelationship + ' ' + dependentKey + ':', e);
        return false;
    }
}

function moveToBlocked(tracker, key, blockedStatus) {
    try {
        tracker.moveToStatus(key, blockedStatus);
        console.log('Moved ' + key + ' to ' + blockedStatus);
    } catch (e) {
        console.warn('Failed to move ' + key + ' to ' + blockedStatus + ':', e);
    }
}

function wireDependencies(tracker, created, taskKeyMap, blocksRelationship, blockedStatus) {
    created.forEach(function(c) {
        if (!c.key || !Array.isArray(c.depends_on) || c.depends_on.length === 0) return;
        var anyLinked = false;
        c.depends_on.forEach(function(depKey) {
            var blockerKey = taskKeyMap[depKey];
            if (!blockerKey) {
                console.warn('Cannot resolve depends_on "' + depKey + '" for ' + c.key + ' — skipping link');
                return;
            }
            if (linkDependency(tracker, blockerKey, c.key, blocksRelationship)) anyLinked = true;
        });
        if (anyLinked) moveToBlocked(tracker, c.key, blockedStatus);
    });
}

function postSummaryComment(tracker, saKey, comment) {
    try {
        tracker.postComment(saKey, comment);
    } catch (e) {
        console.warn('Failed to post summary comment on ' + saKey + ':', e);
    }
}

function action(params) {
    try {
        var saKey = params.ticket && params.ticket.key;
        if (!saKey) {
            return { success: false, error: 'No ticket key in params' };
        }

        console.log('createRepoTasksMulti: processing SA ticket ' + saKey);

        var customParams = params.customParams || (params.jobParams && params.jobParams.customParams) || {};
        var blocksRelationship = customParams.blocksRelationship || 'Blocks';
        var blockedStatus      = customParams.blockedStatus      || 'Blocked';
        var ticketLabels       = customParams.labels             || ['development'];

        var tracker = trackersModule.createTracker(resolveProjectConfig(params), customParams);
        var saTicket = tracker.getIssue(saKey, ['description', 'summary', 'parent']);
        var saFields = saTicket && saTicket.fields ? saTicket.fields : saTicket;
        var description = saFields.description ? saFields.description.toString() : '';

        var parentInfo = saFields.parent;
        var parentKey = parentInfo && typeof parentInfo === 'object' ? parentInfo.key : null;
        if (!parentKey) {
            return { success: false, error: 'SA ticket ' + saKey + ' has no parent ticket' };
        }
        console.log('Parent ticket: ' + parentKey);

        var parentTicket = tracker.getIssue(parentKey, ['summary']);
        var parentFields = parentTicket && parentTicket.fields ? parentTicket.fields : parentTicket;
        var parentSummary = (parentFields.summary || parentKey).toString();

        var repos = parseAffectedRepos(description);
        if (repos.length === 0) {
            return { success: false, error: 'No affected repos found in ' + saKey + ' — ensure writeSolutionAndLabels ran first' };
        }

        var tasks = buildTaskPlan(repos);
        console.log('Flattened into ' + tasks.length + ' task(s) across ' +
            repos.map(function(r) { return typeof r === 'string' ? r : r.name; }).join(', '));

        var baseUrl = getJiraBaseUrl();
        var projectKey = parentKey.split('-')[0];

        // Load existing Sub-tasks under the parent to avoid duplicates
        var existingSummaries = loadExistingSummaries(tracker, parentKey);

        var outcome = createSubTasks(tracker, tasks, projectKey, parentKey, saKey, baseUrl, ticketLabels, existingSummaries);

        // Wire dependencies: blocker Blocks dependent + move dependent to Blocked status
        wireDependencies(tracker, outcome.created, outcome.taskKeyMap, blocksRelationship, blockedStatus);

        // Post summary comment on the SA ticket
        if (outcome.created.length > 0 || outcome.skipped.length > 0) {
            postSummaryComment(tracker, saKey, buildSummaryComment(outcome.created, outcome.skipped, baseUrl));
        }

        var successCount = outcome.created.filter(function(c) { return !c.error; }).length;
        return {
            success: true,
            message: 'Created ' + successCount + ' Sub-task(s) under ' + parentKey + ', skipped ' + outcome.skipped.length,
            created: successCount,
            skipped: outcome.skipped.length
        };

    } catch (error) {
        console.error('Error in createRepoTasksMulti:', error);
        return { success: false, error: error.toString() };
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        action: action,
        parseAffectedRepos: parseAffectedRepos,
        flattenTasks: flattenTasks,
        topologicalSortTasks: topologicalSortTasks,
        buildTaskPlan: buildTaskPlan,
        buildTaskSummary: buildTaskSummary,
        buildTaskDescription: buildTaskDescription,
        decideDuplicate: decideDuplicate,
        extractCreatedKey: extractCreatedKey,
        buildSummaryComment: buildSummaryComment,
        loadExistingSummaries: loadExistingSummaries,
        createSubTasks: createSubTasks,
        wireDependencies: wireDependencies,
        postSummaryComment: postSummaryComment
    };
}

/**
 * Pre-CLI snapshot setup — optional codegraph branch alignment for non-dev agents.
 *
 * Use case: BA / SA / discovery / questions agents need a codegraph snapshot that
 * matches the branch the implementation will eventually target. While dev agents
 * already align the branch in preCliDevelopmentSetup, other agents run against the
 * static checkout created by setup/checkout.sh (usually the repo default branch).
 *
 * Behavior:
 *   1. Optionally chains the agent's original preCliJSAction (configured via
 *      customParams.chainedPreCliJSAction) so existing setup is preserved.
 *   2. Resolves config.git.snapshotBranch through configLoader, which may invoke a
 *      project-specific snapshotBranchResolverFnPath (e.g. based on fixVersion).
 *   3. If a snapshotBranch different from the current HEAD is resolved, checks it
 *      out in targetRepository.workingDir and syncs codegraph.
 *
 * The action is fully backward-compatible: if no snapshotBranchResolverFnPath is
 * configured, or if targetRepository.workingDir is missing, it returns success
 * immediately without touching git state.
 */

var configLoader = require('./configLoader.js');
var prHelper = require('./common/pullRequest.js');

// Canonical copy (gh-823/gh-912): the warning:/note: line filter lives in
// common/pullRequest.js once — this delegate keeps every local call site.
function cleanCommandOutput(output) {
    return prHelper.cleanCommandOutput(output);
}

function runCommand(command, workingDir) {
    var args = { command: command };
    if (workingDir) args.workingDirectory = workingDir;
    return cli_execute_command(args);
}

function lastNonEmptyLine(output) {
    var lines = cleanCommandOutput(output || '').split(/\r?\n/)
        .map(function(line) { return line.trim(); })
        .filter(function(line) { return line; });
    return lines[lines.length - 1] || '';
}

function currentBranch(workingDir) {
    try {
        return lastNonEmptyLine(runCommand('git rev-parse --abbrev-ref HEAD', workingDir));
    } catch (e) {
        return '';
    }
}

function checkoutSnapshotBranch(workingDir, branchName) {
    if (!workingDir || !branchName) return false;

    var current = currentBranch(workingDir);
    if (current === branchName) {
        try {
            runCommand('git pull origin ' + branchName + ' --ff-only', workingDir);
            console.log('preCliSnapshotSetup: already on ' + branchName + ', pulled latest');
            return true;
        } catch (e) {
            console.warn('preCliSnapshotSetup: pull failed:', e.message || e);
            return true; // still on right branch
        }
    }

    try {
        runCommand('git fetch origin ' + branchName, workingDir);
    } catch (e) {
        console.warn('preCliSnapshotSetup: could not fetch origin/' + branchName + ':', e.message || e);
    }

    try {
        runCommand('git checkout ' + branchName, workingDir);
    } catch (e) {
        console.log('preCliSnapshotSetup: local branch missing — creating from origin/' + branchName);
        runCommand('git checkout -B ' + branchName + ' origin/' + branchName, workingDir);
    }

    try {
        runCommand('git pull origin ' + branchName + ' --ff-only', workingDir);
    } catch (e) {
        console.warn('preCliSnapshotSetup: could not fast-forward ' + branchName + ':', e.message || e);
    }

    console.log('preCliSnapshotSetup: checked out snapshot branch ' + branchName + ' in ' + workingDir);
    return true;
}

function syncCodegraph(workspace) {
    try {
        runCommand('codegraph sync "' + workspace + '"', workspace);
        console.log('preCliSnapshotSetup: codegraph sync completed');
        return true;
    } catch (e) {
        console.warn('preCliSnapshotSetup: codegraph sync failed:', e.message || e);
        return false;
    }
}

function action(params) {
    try {
        var actualParams = params.ticket ? params : (params.jobParams || params);
        // In the real Teammate execution path customParams live under jobParams
        // (JavaScriptExecutor.withJobContext puts jobParams/ticket/response at top level);
        // keep the top-level fallback for direct/JSRunner invocations.
        var customParams = (params.jobParams && params.jobParams.customParams) || actualParams.customParams || {};

        // 1. Preserve existing preCliJSAction behavior by chaining.
        var chained = customParams.chainedPreCliJSAction;
        if (chained) {
            try {
                // Paths in agent JSONs are relative to agents/js/.
                var chainedModule = require('./' + chained);
                if (chainedModule && typeof chainedModule.action === 'function') {
                    console.log('preCliSnapshotSetup: chaining ' + chained);
                    var chainedResult = chainedModule.action(params);
                    if (chainedResult === false) {
                        console.warn('preCliSnapshotSetup: chained action returned false — aborting');
                        return false;
                    }
                }
            } catch (chainError) {
                console.warn('preCliSnapshotSetup: chained action failed (non-fatal):', chainError.message || chainError);
            }
        }

        // 2. Resolve config. snapshotBranch is filled by snapshotBranchResolverFnPath if configured.
        // paramsForConfigLoad re-attaches params.ticket (sibling of jobParams in the
        // real Teammate execution path) so snapshotBranchResolverFnPath can key off the
        // ticket's fixVersion — see configLoader.js for details.
        var config = configLoader.loadProjectConfig(configLoader.paramsForConfigLoad(params));
        var snapshotBranch = config.git && config.git.snapshotBranch;
        if (!snapshotBranch) {
            console.log('preCliSnapshotSetup: no snapshotBranch configured — nothing to do');
            return true;
        }

        var targetRepo = config.customParams && config.customParams.targetRepository;
        var workingDir = targetRepo && targetRepo.workingDir;
        if (!workingDir) {
            console.log('preCliSnapshotSetup: no targetRepository.workingDir — skipping checkout');
            return true;
        }

        // 3. Align the dependency checkout with the snapshot branch.
        checkoutSnapshotBranch(workingDir, snapshotBranch);

        // 4. Refresh codegraph index so BA/SA/discovery agents see the aligned snapshot.
        var workspace = config.workingDir || '.';
        syncCodegraph(workspace);

        return true;
    } catch (error) {
        console.error('preCliSnapshotSetup: unexpected error:', error);
        // Never block the agent because of a snapshot setup failure.
        return true;
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action: action };
}

/**
 * Pre-CLI Knowledge Update Setup Action (preCliJSAction for pr_knowledge_update agent)
 *
 * Prepares input context so a CLI agent can distill review-thread pain points
 * from a merged PR/MR into a self-curated, repo-specific knowledge base —
 * without any repo-specific or tracker-specific logic living here. See
 * agents/instructions/knowledge_update/ for the generic read/write protocol
 * the CLI agent follows.
 *
 * This job is intentionally NOT bound to a ticket/tracker. It is driven purely
 * by customParams, so it can be:
 *   - run standalone against any already-merged PR/MR to backfill a knowledge
 *     base in bulk (e.g. looping over a list of historical PR numbers), or
 *   - wired to whatever "PR merged" trigger a project chooses (a webhook, a
 *     scheduled scan of recently-merged PRs, a manual one-off invocation,
 *     etc.) — that trigger mechanism is deliberately out of scope here.
 *
 * customParams.knowledgeDir is the ONLY repo-specific piece of configuration
 * this action reads, and it is entirely optional: when it is not set (the
 * default in this generic config), this action is a no-op — it writes a
 * knowledge_task.md explaining there is nothing to do, and the CLI agent's
 * instructions tell it to stop immediately on seeing that. This mirrors the
 * existing no-op convention for other optional resolver hooks in this repo
 * (e.g. baseBranchResolverFnPath, snapshotBranchResolverFnPath) — a project
 * that hasn't opted in must never fail or produce noise.
 *
 * When knowledgeDir IS configured, one of three input modes is used (checked
 * in this order):
 *
 *   1. Direct content (customParams.diffText and/or customParams.discussionsMarkdown
 *      already provided) — no SCM calls at all. Use this to feed the agent
 *      diff-only or conversations-only material gathered by some external
 *      process (e.g. a bulk-export script, or a PR whose head branch/API
 *      access is no longer available).
 *
 *   2. Direct PR/MR reference (customParams.prNumber) — fetches PR details,
 *      diff text, and discussions straight from the SCM API for that single
 *      PR/MR number. This is the primary way to run this job standalone,
 *      e.g. `dmtools run pr_knowledge_update.json --customParams
 *      '{"knowledgeDir":"...","prNumber":"123"}'`, including in a loop over
 *      many historical PR numbers to backfill a knowledge base quickly.
 *
 *   3. Ticket-based (only if this action is invoked with a ticket in context,
 *      e.g. params.ticket) — finds the most recently MERGED PR/MR for that
 *      ticket via findMergedPRForTicket(). Kept for projects that prefer to
 *      drive this from their own ticket-status automation.
 *
 * In every mode, diff text and discussions are each optional on their own —
 * a PR with no review comments (diff-only) or a PR whose diff could not be
 * fetched (discussions-only) both still produce useful, if narrower, context.
 * Only the total absence of both is treated as "nothing to learn from".
 */

var configLoader = require('./configLoader.js');
const gh = require('./common/githubHelpers.js');

function writeNoOpMarker(inputFolder, reason) {
    file_write({
        path: inputFolder + '/knowledge_task.md',
        content: '# Knowledge Update — nothing to do\n\n' + reason +
            '\n\nDo NOT read or modify any knowledge/ directory this run. Stop after ' +
            'confirming this file says so; do not attempt to find one yourself.\n'
    });
}

function writeTaskMarker(inputFolder, knowledgeDir, prDetails) {
    var prLine = prDetails && prDetails.number
        ? 'Source PR/MR: [#' + prDetails.number + '](' + (prDetails.html_url || 'unknown') + ')\n\n'
        : 'Source PR/MR: unknown (content supplied directly, no PR reference available)\n\n';

    file_write({
        path: inputFolder + '/knowledge_task.md',
        content: '# Knowledge Update Task\n\n' + prLine +
            'Target knowledge directory (relative to your current working directory): `' +
            knowledgeDir + '`\n\n' +
            'Follow the read/write protocol described in your instructions to distill ' +
            'generalized heuristics from pr_discussions.md and/or pr_diff.txt (either may be ' +
            'absent — work with whichever is available) into that directory. Do not invent a ' +
            'different location.\n'
    });
}

/**
 * Resolves how to source PR context, in priority order:
 * direct content > direct PR reference > ticket-based lookup.
 *
 * Returns { prDetails, diffText, discussionsMarkdown, discussionsRaw } or null
 * if nothing usable could be resolved (caller writes the no-op marker).
 */
function resolvePrContext(scm, customParams, ticketKey) {
    // Mode 1: direct content — fully offline, no SCM calls.
    if (customParams.diffText || customParams.discussionsMarkdown) {
        console.log('Knowledge update: using directly supplied diff/discussions content (no SCM calls).');
        var directPr = {
            number: customParams.prNumber || null,
            html_url: customParams.prUrl || null,
            title: customParams.prTitle || null,
            state: 'merged'
        };
        return {
            prDetails: directPr,
            diffText: customParams.diffText || null,
            discussionsMarkdown: customParams.discussionsMarkdown || null,
            discussionsRaw: null
        };
    }

    // Mode 2: direct PR/MR reference — the primary standalone/backfill entry point.
    if (customParams.prNumber) {
        console.log('Knowledge update: resolving PR/MR #' + customParams.prNumber + ' directly.');
        var prByNumber = gh.getPRDetails(scm, customParams.prNumber);
        if (!prByNumber) {
            console.warn('Could not fetch PR/MR #' + customParams.prNumber + ' — skipping.');
            return null;
        }
        return fetchDiffAndDiscussions(scm, prByNumber);
    }

    // Mode 3: ticket-based — only when this action happens to be invoked with a ticket.
    if (ticketKey) {
        console.log('Knowledge update: resolving merged PR/MR for ticket', ticketKey, '.');
        var prByTicket = gh.findMergedPRForTicket(scm, ticketKey);
        if (!prByTicket) {
            console.warn('No merged PR found for ticket', ticketKey, '— skipping.');
            return null;
        }
        var prDetails = gh.getPRDetails(scm, prByTicket.number) || prByTicket;
        return fetchDiffAndDiscussions(scm, prDetails);
    }

    return null;
}

function fetchDiffAndDiscussions(scm, prDetails) {
    var diffText = null;
    if (typeof scm.getDiffText === 'function') {
        diffText = scm.getDiffText(prDetails.number);
    }
    if (!diffText) {
        console.warn('Diff text unavailable for PR #' + prDetails.number + ' — proceeding with discussions only (if any).');
    }

    console.log('Fetching discussions for PR/MR #' + prDetails.number + '...');
    var discussionData = gh.fetchDiscussionsAndRawData(scm, prDetails.number) || {};

    return {
        prDetails: prDetails,
        diffText: diffText,
        discussionsMarkdown: discussionData.markdown || null,
        discussionsRaw: discussionData.rawThreads || null
    };
}

function action(params) {
    try {
        var actualParams = params.inputFolderPath ? params : (params.jobParams || params);
        var inputFolder = actualParams.inputFolderPath;
        var config = configLoader.loadProjectConfig(params.jobParams || params);
        var customParams = (params.jobParams && params.jobParams.customParams) || actualParams.customParams || {};
        var ticketKey = actualParams.ticket ? (actualParams.ticket.key || actualParams.ticket) : (customParams.ticket || null);

        console.log('=== Knowledge update setup ===');

        var knowledgeDir = customParams.knowledgeDir;
        if (!knowledgeDir) {
            console.log('No customParams.knowledgeDir configured for this repo — skipping (no-op).');
            writeNoOpMarker(inputFolder,
                'This repo has not configured `customParams.knowledgeDir`, so there is no ' +
                'review-knowledge base to update yet.');
            return { success: true, skipped: true, reason: 'knowledgeDir not configured' };
        }

        var hasDirectContent = !!(customParams.diffText || customParams.discussionsMarkdown);
        var scm = hasDirectContent ? null : configLoader.createScm(config);

        var resolved = resolvePrContext(scm, customParams, ticketKey);
        if (!resolved) {
            writeNoOpMarker(inputFolder,
                'No PR/MR context could be resolved. Provide `customParams.prNumber` (direct ' +
                'backfill run), `customParams.diffText`/`discussionsMarkdown` (direct content), ' +
                'or invoke this action with a ticket in context.');
            return { success: true, skipped: true, reason: 'no PR context resolved' };
        }

        if (!resolved.diffText && !resolved.discussionsMarkdown) {
            console.warn('Neither diff nor discussions could be obtained — nothing to learn from.');
            writeNoOpMarker(inputFolder,
                'Both the diff and the discussions were unavailable for this PR/MR — there is ' +
                'nothing to distill.');
            return { success: true, skipped: true, reason: 'no diff or discussions available' };
        }

        var prDetailsForContext = resolved.prDetails || {};
        gh.writePRContext(inputFolder, prDetailsForContext, resolved.diffText, resolved.discussionsMarkdown, resolved.discussionsRaw);
        writeTaskMarker(inputFolder, knowledgeDir, resolved.prDetails);

        console.log('✅ Knowledge update setup complete — target:', knowledgeDir);

        return {
            success: true,
            prNumber: prDetailsForContext.number || null,
            prUrl: prDetailsForContext.html_url || null,
            knowledgeDir: knowledgeDir
        };

    } catch (error) {
        console.error('❌ Error in preCliKnowledgeUpdateSetup:', error);
        return { success: false, error: error.toString() };
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action, writeNoOpMarker, resolvePrContext };
}

/**
 * Runs project-specific prerequisite/setup commands before the CLI agent starts.
 *
 * Configured via customParams.setupCommands: an array of either plain command
 * strings or objects { command, name, workingDir, allowFailure }.
 *
 * - Plain strings and entries without `allowFailure: false` are non-fatal:
 *   a failure is logged and the loop continues (useful for warm-up/caching
 *   steps that shouldn't block the whole pipeline).
 * - `allowFailure: false` makes the step required: a failure throws, stopping
 *   development before the CLI agent runs (useful for prerequisite checks
 *   like "required credentials are present").
 *
 * Used by: preCliDevelopmentSetup.js (story_development), preCliReworkSetup.js
 * (pr_rework) — runs once per ticket, right after the git branch is checked
 * out and before the CLI coding agent starts.
 *
 * ⚠️ IMPORTANT — every command here goes through cli_execute_command, which:
 * 1. Only allows executables in the whitelist: git, gh, dmtools, npm, yarn,
 *    docker, kubectl, terraform, ansible, aws, gcloud, az (base list). Anything
 *    else (bash, mvn, gradle, test, python3, ...) MUST be added via
 *    params.envVariables.CLI_ALLOWED_COMMANDS (comma-separated) on the agent
 *    JSON, e.g. { "envVariables": { "CLI_ALLOWED_COMMANDS": "bash,mvn" } }.
 * 2. Rejects any command string containing shell metacharacters —
 *    `;`, `&&`, `||`, `|`, `>`, `<`, `` ` ``, `$(...)`, `${...}` — even if the
 *    leading executable is whitelisted. There is NO way to pass a compound
 *    command (e.g. "test -n \"$X\" && echo ok") directly.
 *    If you need conditional/compound logic, put it inside a checked-in .sh
 *    script file and invoke that file with a single simple command
 *    (e.g. "bash agents/scripts/check_required_env_vars.sh VAR1 VAR2") — the
 *    metacharacter check only inspects the command string passed to
 *    cli_execute_command, not the contents of a script it runs.
 */

// Required setup command failures embed the raw tool output (e.g. full `mvn`/`gradle`
// console output, which can run into megabytes) in the thrown Error's message. Callers
// (preCliDevelopmentSetup.js, preCliReworkSetup.js) post that message straight into a
// Jira/tracker comment; trackers reject oversized comments (e.g. Jira's ~350000 char
// limit) and the resulting post failure can end up silently swallowed, leaving the
// ticket with zero visibility into why setup failed. Cap the embedded output here, at
// the source, so every consumer of this error automatically gets a bounded message.
var MAX_SETUP_ERROR_CHARS = 8000;

function truncateSetupError(text) {
    if (typeof text !== 'string' || text.length <= MAX_SETUP_ERROR_CHARS) {
        return text;
    }
    // Keep the head (command/context) and tail (usually the actual failure/exception)
    // since Maven/Gradle failures are typically reported at the very end of the output.
    var headLen = Math.floor(MAX_SETUP_ERROR_CHARS * 0.4);
    var tailLen = MAX_SETUP_ERROR_CHARS - headLen;
    var omitted = text.length - headLen - tailLen;
    return text.slice(0, headLen) +
        '\n... [truncated ' + omitted + ' char(s) — see CLI logs for full output] ...\n' +
        text.slice(text.length - tailLen);
}

function runSetupCommands(customParams, defaultWorkingDir) {
    var commands = (customParams && customParams.setupCommands) || [];
    if (!Array.isArray(commands) || commands.length === 0) {
        return { ran: 0, results: [] };
    }

    var results = [];
    for (var i = 0; i < commands.length; i++) {
        var entry = commands[i];
        var isString = typeof entry === 'string';
        var command = isString ? entry : (entry && entry.command);
        if (!command) continue;

        var workingDir = (!isString && entry.workingDir) || defaultWorkingDir || null;
        var allowFailure = isString ? true : (entry.allowFailure !== false);
        var name = (!isString && entry.name) || command;

        try {
            console.log('Running setup command "' + name + '": ' + command);
            var args = { command: command };
            if (workingDir) args.workingDirectory = workingDir;
            var output = cli_execute_command(args);
            results.push({ name: name, success: true, output: output });
        } catch (e) {
            var errorText = e && e.message ? e.message : String(e);
            // Log the BOUNDED text only. The full errorText stays in `results` (callers and
            // buildSetupWarningsMarkdown apply their own bound). A multi-megabyte tool output
            // printed as a single console line makes the GitHub Actions log processor take
            // minutes (dm.ai#635: two 500 KB lines = ~800 s of a 13 s test run).
            console.warn('Setup command "' + name + '" failed:', truncateSetupError(errorText));
            results.push({ name: name, success: false, error: errorText });
            if (allowFailure === false) {
                throw new Error('Required setup command failed: ' + name + ' — ' + truncateSetupError(errorText));
            }
        }
    }
    return { ran: results.length, results: results };
}

/**
 * Builds a markdown summary of any non-fatal ("allowFailure" — the default) setup
 * command failures from a runSetupCommands() result, or null if none failed.
 *
 * Non-fatal failures are, by design, only logged to the CI console (see
 * runSetupCommands() above) — the CLI coding agent never sees them unless the caller
 * writes this out to an input file. Without that, a step like "build the project's
 * Docker test image" can fail for a genuine, agent-fixable content reason (e.g. a bad
 * migration file) and the agent will start working on the ticket with zero awareness
 * that anything is wrong, only to hit a confusing downstream failure later (or worse,
 * silently ship a broken fix). Callers should write this to e.g. `setup_warnings.md` in
 * the input folder whenever it returns non-null, so the CLI agent can read it as context
 * and attempt a fix, the same way it already does for merge_conflicts.md.
 */
function buildSetupWarningsMarkdown(runResult) {
    var results = (runResult && runResult.results) || [];
    var failures = results.filter(function(r) { return r && r.success === false; });
    if (failures.length === 0) {
        return null;
    }
    var lines = [
        '# Setup Command Warnings',
        '',
        'The following setup command(s) failed but were configured as non-fatal ' +
            '(allowFailure is not set to false), so environment setup continued. ' +
            'If this failure is caused by a fixable issue in the code (e.g. a bad ' +
            'migration, a broken test, a compile error), please investigate and fix it ' +
            'as part of this task.',
        ''
    ];
    for (var i = 0; i < failures.length; i++) {
        lines.push('## ' + failures[i].name);
        lines.push('');
        lines.push('```');
        lines.push(truncateSetupError(failures[i].error || ''));
        lines.push('```');
        lines.push('');
    }
    return lines.join('\n');
}

module.exports = {
    runSetupCommands: runSetupCommands,
    truncateSetupError: truncateSetupError,
    buildSetupWarningsMarkdown: buildSetupWarningsMarkdown
};

/**
 * Shared encoded config builder for SM Agent and autoStart triggers.
 *
 * Reads the target agent JSON, copies its params, merges project-specific
 * instructions from .dmtools/config.js, and produces the URL-encoded
 * `encoded_config` payload that `ai-teammate.yml` consumes.
 *
 * Keeping this logic in one place guarantees that a workflow triggered by
 * SM, by autoStart, or manually with the same builder always receives the
 * same resolved params (cliPrompts, customParams, feedbackLoop, etc.).
 */

var configLoader = require('../configLoader.js');
var validateInputJql = require('./validateInputJql.js');
var trackers = require('./trackers.js');

function extractAgentName(configFile) {
    if (!configFile) return '';
    var name = configFile;
    var slashIdx = name.lastIndexOf('/');
    if (slashIdx !== -1) name = name.substring(slashIdx + 1);
    if (name.indexOf('.json') !== -1) name = name.replace('.json', '');
    return name;
}

/**
 * Resolve the full path to an agent config JSON.
 *
 * @param {Object|string} rule - Either a rule object with a `configFile`
 *   property or a bare config file name/path.
 * @param {Object} effectiveConfig - Loaded project config; its
 *   `agentConfigsDir` is used when only a bare filename is provided.
 * @returns {string|null} Resolved config file path.
 */
function resolveConfigFile(rule, effectiveConfig) {
    var cf = (rule && rule.configFile) || rule;
    if (!cf || typeof cf !== 'string') return null;
    if (cf.indexOf('/') !== -1) return cf;
    var dir = effectiveConfig && effectiveConfig.agentConfigsDir;
    if (dir) {
        return dir.replace(/\/$/, '') + '/' + cf;
    }
    return cf;
}

function tryReadJson(path) {
    try {
        var raw = file_read({ path: path });
        if (raw && raw.trim()) {
            return JSON.parse(raw);
        }
    } catch (e) {
        // ignore
    }
    return null;
}

/**
 * Resolve the directory portion of a file path.
 * "agents/story_solution_e2e.json" → "agents/"
 */
function dirOf(filePath) {
    var idx = filePath.lastIndexOf('/');
    return idx >= 0 ? filePath.substring(0, idx + 1) : '';
}

/**
 * Recursively resolve parent inheritance for an agent JSON config.
 *
 * Supports `parent.merge` for array fields (currently only params.cliPrompts).
 * Per the JSON config spec: merged array = parent items + child items.
 *
 * @param {Object} agentJson   - Parsed agent JSON (may contain a `parent` block).
 * @param {string} agentPath   - File path used to resolve relative `parent.path` values.
 * @param {number} [depth=0]   - Recursion guard (max 10 levels).
 * @returns {Object} Fully-resolved `params` object with parent inheritance applied.
 */
function resolveParentMerge(agentJson, agentPath, depth) {
    depth = depth || 0;
    var childParams = (agentJson && agentJson.params) ? agentJson.params : {};

    if (!agentJson || !agentJson.parent || !agentJson.parent.path || depth > 10) {
        return childParams;
    }

    var parentRelPath = agentJson.parent.path;
    var parentAbsPath = dirOf(agentPath) + parentRelPath;
    var parentJson = tryReadJson(parentAbsPath);
    if (!parentJson) {
        return childParams;
    }

    // Resolve grandparent chain first
    var parentParams = resolveParentMerge(parentJson, parentAbsPath, depth + 1);

    // Deep-merge: parent as base, child overrides
    var merged = configLoader.deepMerge(parentParams, childParams);

    // Apply merge directives — merge = parent items prepended before child items
    var mergeFields = (agentJson.parent.merge && Array.isArray(agentJson.parent.merge))
        ? agentJson.parent.merge : [];

    mergeFields.forEach(function(fieldPath) {
        // Accept both "params.cliPrompts" and bare "cliPrompts"
        var key = fieldPath;
        if (key.indexOf('params.') === 0) {
            key = key.substring('params.'.length);
        }
        var parentArr = Array.isArray(parentParams[key]) ? parentParams[key] : [];
        var childArr  = Array.isArray(childParams[key])  ? childParams[key]  : [];
        merged[key] = parentArr.concat(childArr);
    });

    return merged;
}

/**
 * Read contentOutput.target from a customParams object, if present.
 */
function readContentOutputTarget(customParams) {
    if (customParams && customParams.contentOutput &&
            typeof customParams.contentOutput.target === 'string') {
        return customParams.contentOutput.target;
    }
    return null;
}

function isWikiOutputTarget(target) {
    return target === 'confluence' || target === 'wiki';
}

function hasConfluencePrompts(source) {
    return Boolean(source && source.cliPromptsByTracker && source.cliPromptsByTracker.confluence);
}

/**
 * Resolve the 'confluence' tracker-prompt override for an agent.
 *
 * When the effective customParams (agent JSON customParams, overridable via the project
 * config's jobParamPatches.<agent>.customParams) route generated content exclusively to
 * Confluence (contentOutput.target === 'confluence'), tracker-specific CLI prompts must be
 * selected by the 'confluence' key so the CLI agent authors Markdown instead of tracker
 * markup (e.g. Jira wiki). Returns 'confluence' only when confluence tracker prompts are
 * actually declared (agent JSON or project config); otherwise null — callers then keep the
 * default tracker, matching the runtime fallback in CliCommandBuilder.
 */
function resolveConfluenceTrackerOverride(agentParamsRoot, effectiveConfig, agentName) {
    var patches = effectiveConfig && effectiveConfig.jobParamPatches && effectiveConfig.jobParamPatches[agentName];
    var target = readContentOutputTarget(patches && patches.customParams) ||
        readContentOutputTarget(agentParamsRoot && agentParamsRoot.customParams);
    if (!isWikiOutputTarget(target)) {
        return null;
    }
    return (hasConfluencePrompts(agentParamsRoot) || hasConfluencePrompts(effectiveConfig)) ? 'confluence' : null;
}

/**
 * Derive the project key used to resolve a project-specific agent JSON
 * (e.g. "agents/pr_review.json" -> "ai_teammate/myproject/pr_review.json").
 * Explicit rule.projectKey wins; otherwise the basename of the loaded
 * project config path is used unless it is the generic "config".
 *
 * @param {Object|string} rule - Rule object or resolved config file path.
 * @param {Object} effectiveConfig - Loaded project config.
 * @returns {string} Project key ('' when none can be derived).
 */
function resolveProjectKey(rule, effectiveConfig) {
    var projectKey = (rule && rule.projectKey) || '';
    if (!projectKey && effectiveConfig && effectiveConfig._configPath) {
        var cp = effectiveConfig._configPath;
        var base = cp.substring(cp.lastIndexOf('/') + 1).replace(/\.js$/, '');
        if (base && base !== 'config') projectKey = base;
    }
    return projectKey;
}

/**
 * Resolve which agent JSON file to read: the project-specific variant
 * ("ai_teammate/<projectKey>/<filename>") when it exists, otherwise the
 * generic resolved config file.
 */
function resolveAgentJsonPath(resolvedCf, projectKey) {
    var agentJsonPath = resolvedCf;
    if (projectKey) {
        var filename = resolvedCf.replace(/^.*\//, '');
        var projectSpecific = 'ai_teammate/' + projectKey + '/' + filename;
        if (tryReadJson(projectSpecific)) {
            agentJsonPath = projectSpecific;
        }
    }
    return agentJsonPath;
}

/**
 * True when a string param carries a JQL placeholder that must be
 * interpolated against the project config.
 */
function needsJqlInterpolation(value) {
    return value.indexOf('{jiraProject}') !== -1 || value.indexOf('{parentTicket}') !== -1;
}

/**
 * Copy a single agent-JSON param value into the encoded params payload,
 * applying the JQL interpolation to strings carrying {jiraProject} /
 * {parentTicket} placeholders and deep-copying structured values.
 * cliPromptsByTracker is NOT copied: tracker prompts are already resolved
 * and flattened into cliPrompts (resolveInstructions); copying the map
 * would make the runtime merge them a second time.
 */
function copyParamValue(p, paramKey, value, effectiveConfig) {
    if (typeof value === 'string') {
        if (needsJqlInterpolation(value)) {
            p[paramKey] = configLoader.interpolateJql(value, effectiveConfig);
        } else {
            p[paramKey] = value;
        }
    } else if (typeof value === 'boolean' || typeof value === 'number') {
        p[paramKey] = value;
    } else if (Array.isArray(value)) {
        p[paramKey] = value.slice();
    } else if (typeof value === 'object' && value !== null) {
        p[paramKey] = JSON.parse(JSON.stringify(value));
    }
}

/**
 * Copy all scalar/array/object params from the resolved agent JSON into the
 * encoded params payload (skipping inputJql and cliPromptsByTracker).
 */
function copyAgentParams(p, agentParamsRoot, effectiveConfig) {
    var skipKeys = { inputJql: true, cliPromptsByTracker: true };
    Object.keys(agentParamsRoot).forEach(function(paramKey) {
        if (skipKeys[paramKey]) return;
        copyParamValue(p, paramKey, agentParamsRoot[paramKey], effectiveConfig);
    });
}

/**
 * Copy the nested agentParams / customParams objects from the agent JSON
 * into the encoded params payload (agentParams deep-merged from empty,
 * customParams shallow-copied).
 */
function copyNestedAgentObjects(p, agentParamsRoot) {
    var agentParams = agentParamsRoot.agentParams;
    if (agentParams && typeof agentParams === 'object') {
        p.agentParams = configLoader.deepMerge({}, agentParams);
    }
    var agentCustomParams = agentParamsRoot.customParams;
    if (agentCustomParams && typeof agentCustomParams === 'object') {
        p.customParams = Object.assign({}, agentCustomParams);
    }
}

/**
 * Apply the instruction-level resolutions from resolveInstructions():
 * a full instructions override lands in agentParams.instructions;
 * additionalInstructions are appended.
 */
function applyInstructionExtras(p, resolved) {
    if (resolved.instructionsOverridden) {
        if (!p.agentParams) p.agentParams = {};
        p.agentParams.instructions = resolved.instructions;
    }
    if (resolved.additionalInstructions && resolved.additionalInstructions.length > 0) {
        p.additionalInstructions = resolved.additionalInstructions;
    }
}

/**
 * Apply the resolved CLI prompts: 'replace' strategy swaps the JSON-inherited
 * cliPrompts entirely, the default 'merge' strategy appends after them.
 * A resolved cliPrompt override wins last.
 */
function applyCliPrompts(p, resolved) {
    if (resolved.cliPrompts && resolved.cliPrompts.length > 0) {
        if (resolved.cliPromptsStrategy === 'replace') {
            // replace: config.js prompts replace the JSON-inherited cliPrompts entirely
            p.cliPrompts = resolved.cliPrompts;
        } else {
            // merge (default): append config.js prompts after the JSON-inherited ones
            var existing = Array.isArray(p.cliPrompts) ? p.cliPrompts : [];
            p.cliPrompts = existing.concat(resolved.cliPrompts);
        }
    }
    if (resolved.cliPrompt) {
        p.cliPrompt = resolved.cliPrompt;
    }
}

/**
 * Apply the agentParamPatch / jobParamPatch from the project config. The
 * jobParamPatch deep-merges into the whole params payload, so it is applied
 * last and its result is returned (p may be replaced by the merge).
 */
function applyConfigPatches(p, resolved) {
    if (resolved.agentParamPatch) {
        if (!p.agentParams) p.agentParams = {};
        p.agentParams = configLoader.deepMerge(p.agentParams, resolved.agentParamPatch);
    }
    if (resolved.jobParamPatch) {
        p = configLoader.deepMerge(p, resolved.jobParamPatch);
    }
    return p;
}

/**
 * Resolve the Jira field-name override for story_acceptance_criteria agents
 * from config.jira.fields.acceptanceCriteria (null when not configured).
 */
function resolveFieldNameOverride(agentName, effectiveConfig) {
    var jiraFields = effectiveConfig.jira && effectiveConfig.jira.fields;
    if (!jiraFields) return null;
    var fieldMap = {
        'story_acceptance_criteria': jiraFields.acceptanceCriteria,
        'story_acceptance_criterias': jiraFields.acceptanceCriteria
    };
    return fieldMap[agentName] || null;
}

/**
 * Build the metadata block for the encoded payload: agentId and/or contextId
 * (upper-cased project key). Returns null when both are absent.
 */
function buildMetadata(agentId, contextId) {
    if (!agentId && !contextId) return null;
    var metadata = {};
    if (agentId) metadata.agentId = agentId;
    if (contextId) metadata.contextId = contextId;
    return metadata;
}

/**
 * Build the encoded config payload for a workflow dispatch.
 *
 * @param {string} ticketKey - Ticket key to process.
 * @param {Object|string} rule - Rule object or resolved config file path.
 * @param {Object} effectiveConfig - Project config from configLoader.
 * @param {boolean} [isLocal] - When true, marks the built config with
 *   `customParams.localTeammate = true` so the job it starts knows it is
 *   running locally (via smAgent's runTeammateLocally/forceLocalTeammate path)
 *   rather than as a GitHub Actions workflow_dispatch. Consumed by
 *   autoStart.js's triggerConfiguredWorkflowForTicket() to keep any further
 *   autoStartReview/autoStartRework chaining on the same machine instead of
 *   dispatching to GitHub Actions.
 * @returns {string} URL-encoded JSON string for workflow_dispatch `encoded_config`.
 */
function buildEncodedConfig(ticketKey, rule, effectiveConfig, isLocal) {
    // One owner of the key rules (validateInputJql): Jira PROJECT-123, GitHub gh-N / owner/repo#N /
    // #N / N and a bare numeric Azure DevOps work item id (#804). Injection-shaped keys still fail.
    if (!validateInputJql.isValidTicketKey(ticketKey)) {
        throw new Error('Invalid ticket key: "' + ticketKey +
            '". Expected a Jira key (PROJECT-123), a GitHub issue key or an Azure DevOps work item id');
    }
    var provider = trackers.createTracker(effectiveConfig, {}).provider();
    var p = { inputJql: validateInputJql.inputJqlForKey(ticketKey, provider) };
    var resolvedCf = resolveConfigFile(rule, effectiveConfig);
    var projectKey = resolveProjectKey(rule, effectiveConfig);
    var agentParamsRoot = {};

    if (resolvedCf) {
        var agentJsonPath = resolveAgentJsonPath(resolvedCf, projectKey);
        var agentJson = tryReadJson(agentJsonPath);
        if (agentJson && agentJson.params) {
            agentParamsRoot = resolveParentMerge(agentJson, agentJsonPath);
            copyAgentParams(p, agentParamsRoot, effectiveConfig);
            copyNestedAgentObjects(p, agentParamsRoot);
        }
    }

    if (effectiveConfig && resolvedCf) {
        var agentName = extractAgentName(resolvedCf);
        var trackerOverride = resolveConfluenceTrackerOverride(agentParamsRoot, effectiveConfig, agentName);
        var resolved = configLoader.resolveInstructions(agentName, null, effectiveConfig, agentParamsRoot.cliPromptsByTracker,
            trackerOverride ? { trackerOverride: trackerOverride } : undefined);

        applyInstructionExtras(p, resolved);
        applyCliPrompts(p, resolved);
        p = applyConfigPatches(p, resolved);

        var fieldName = resolveFieldNameOverride(agentName, effectiveConfig);
        if (fieldName) {
            p.fieldName = fieldName;
        }
    }

    if (effectiveConfig && effectiveConfig._configPath) {
        if (!p.customParams) p.customParams = {};
        p.customParams.configPath = effectiveConfig._configPath;
    }

    if (isLocal) {
        if (!p.customParams) p.customParams = {};
        p.customParams.localTeammate = true;
    }

    if (!p.agentParams) p.agentParams = {};

    var agentId = resolvedCf ? extractAgentName(resolvedCf) : null;
    var contextId = projectKey ? projectKey.toUpperCase() : null;
    var metadata = buildMetadata(agentId, contextId);
    if (metadata) {
        p.metadata = metadata;
    }

    return encodeURIComponent(JSON.stringify({ params: p }));
}


module.exports = {
    extractAgentName: extractAgentName,
    resolveConfigFile: resolveConfigFile,
    resolveParentMerge: resolveParentMerge,
    resolveConfluenceTrackerOverride: resolveConfluenceTrackerOverride,
    buildEncodedConfig: buildEncodedConfig,
    resolveProjectKey: resolveProjectKey,
    resolveAgentJsonPath: resolveAgentJsonPath,
    copyParamValue: copyParamValue,
    needsJqlInterpolation: needsJqlInterpolation,
    copyAgentParams: copyAgentParams,
    copyNestedAgentObjects: copyNestedAgentObjects,
    applyInstructionExtras: applyInstructionExtras,
    applyCliPrompts: applyCliPrompts,
    applyConfigPatches: applyConfigPatches,
    resolveFieldNameOverride: resolveFieldNameOverride,
    buildMetadata: buildMetadata
};

