#!/usr/bin/env node
// crap4js CLI entry point.
//
// Usage:
//   crap4js                  Analyze all .js/.jsx/.ts/.tsx/.mjs/.cjs under src/.
//   crap4js --changed        Analyze git-changed files under src/.
//   crap4js <path>...        Analyze explicit files / directories.
//   crap4js --help           Print this help and exit 0.
//   crap4js --coverage <p>   Override coverage file (default coverage/coverage-final.json).
//   crap4js --threshold <n>  Override CRAP threshold (default 8.0).
//   crap4js --metric <m>     Complexity metric: cyclomatic (default) | cognitive.
//   crap4js --run-tests      Run `nyc node --test` before analyzing.
//   crap4js profile [...]    Run instrumented tests and report per-function timing.
//   crap4js file-naming [...]  Flag mechanical file names (generic/numeric stems).
//   crap4js nesting [...]    Fail functions nested deeper than 5 levels.
//   crap4js class-size [...]  Fail god classes (>25 methods or WMC > 80).
//   crap4js weight-of-class [...]  Fail data-heavy classes (fields ratio > 0.33).
//   crap4js unused-code [...]  Flag module-private declarations never referenced.
//   crap4js unused-files [...]  Flag source files never imported.
//   crap4js banned-imports [--from G --forbid G --message M]... [paths...]
//                            Enforce architectural import boundaries.
//   crap4js magic-constants [paths...]
//                            Flag hex colors outside constants and literals
//                            repeated 3+ times per file.
//   crap4js duplicates [--threshold N] [--min-tokens N] [--min-lines N]
//                      [--report percentage|clones] [--ignore-locals]
//                      [--ignore-literals] [--ignore-identifiers]
//                      [--ignore-imports] [--skip-duplicate-files]
//                      [--exclude GLOB]... [--source PATH]... [paths...]
//                            Flag duplicated token windows within/across
//                            files; the ignore flags opt into renamed-clone
//                            and literal masking, clones mode reports one
//                            violation per clone group.
//   crap4js test-assertions [paths...]
//                            Flag test() bodies with zero assertion calls.
//   crap4js folder-structure Flag src/ dirs with loose (direct) files.
//   crap4js skill            Print the crap4js profiling skill for AI agents.
//
// The first argument selects a subcommand when it is exactly `profile`,
// `file-naming`, `nesting`, `class-size`, `weight-of-class`, `unused-code`,
// `unused-files`, `banned-imports`, `magic-constants`, `duplicates`,
// `test-assertions`, `folder-structure`, `mutation`, or `skill`;
// anything else is analyzed as before.
//
// Exit codes: 0 success; 1 usage error; 2 CRAP/profile threshold exceeded
// or gate-check violations.

import path from 'node:path';
import { analyze } from './analyzer.js';
import { formatReport } from './report.js';
import { buildBaseline, compareBaseline, formatComparison, ratchetDown, readBaseline, writeBaseline } from './baseline.js';
import { changedFiles, expandPaths, findSourceFiles } from './files.js';
import { runTests } from './runtests.js';
import { runFileNaming } from './fileNaming.js';
import { runNesting } from './nesting.js';
import { runClassSize } from './classSize.js';
import { runWeightOfClass } from './weightOfClass.js';
import { runUnusedCode } from './unusedCode.js';
import { runUnusedFiles } from './unusedFiles.js';
import { runBannedImports } from './bannedImports.js';
import { runMagicConstants } from './magicConstants.js';
import { runDuplicates } from './duplicates.js';
import { runTestAssertions } from './testAssertions.js';
import { runFolderStructure } from './folderStructure.js';
import { runMutation } from './mutation.js';
import { parseProfileArgs, runProfile } from './profile.js';
import { runSkill } from './skill.js';
import { isMain } from './mainGuard.js';

const DEFAULT_THRESHOLD = 8.0;
const DEFAULT_COVERAGE = 'coverage/coverage-final.json';
const METRICS = new Set(['cyclomatic', 'cognitive']);

function usage() {
  return [
    'Usage:',
    '  crap4js                  Analyze all .js/.jsx/.ts/.tsx/.mjs/.cjs files under src/',
    '  crap4js --changed        Analyze git-changed source files under src/',
    '  crap4js <path>...        Analyze explicit files / directories (expanded)',
    '  crap4js --help           Print this help message',

// CRAP (Change Risk Anti-Patterns) metric formula.
//
//   CRAP = CC^2 * (1 - coverage)^3 + CC
//
// where CC is the cyclomatic complexity (integer >= 1) and `coverage` is a
// fraction in [0, 1]. When coverage is unknown (null), the score is null and
// is reported as "N/A".

/**
 * Compute the CRAP score for a single method.
 *
 * @param {number} cc        Cyclomatic complexity (>= 1).
 * @param {number|null} coverage  Statement-coverage fraction in [0, 1], or null.
 * @returns {number|null}    CRAP score, or null when coverage is unknown.
 */
export function crapScore(cc, coverage) {
  if (coverage == null) return null;
  const complexity = Number(cc);
  const uncovered = 1.0 - coverage;
  return complexity * complexity * uncovered * uncovered * uncovered + complexity;
}
// CRAP baseline ratchet.
//
// A baseline is a JSON snapshot of per-function CRAP scores. Comparing a fresh
// analysis against it lets a project freeze today's debt and only ever go down:
//   - a function present in the baseline fails if its CRAP grows (beyond a
//     small epsilon that absorbs float noise);
//   - a function absent from the baseline (new or renamed) fails if its CRAP
//     exceeds the threshold;
//   - functions whose CRAP dropped are reported as improvements.
//
// Keys are `file::name`; duplicate names within a file get a `#n` suffix in
// source order, so the key survives line shifts but not reordering of
// same-named functions (acceptable — those are rare and fail safe as "new").

import { readFileSync, writeFileSync } from 'node:fs';

export const BASELINE_VERSION = 1;
// Absorbs rounding/float noise only; any real change in complexity or coverage moves CRAP by more.
const EPSILON = 0.5;

/** Stable key per metric: file::name with #n for repeated names in a file. */
export function keyMetrics(metrics) {
  const byFile = new Map();
  const sorted = [...metrics].sort((a, b) =>
    a.file === b.file ? a.startLine - b.startLine : a.file < b.file ? -1 : 1,
  );
  const out = [];
  for (const m of sorted) {
    const seen = byFile.get(m.file) || new Map();
    byFile.set(m.file, seen);
    const n = seen.get(m.methodName) || 0;
    seen.set(m.methodName, n + 1);
    out.push({ key: `${m.file}::${m.methodName}${n ? `#${n + 1}` : ''}`, metric: m });
  }
  return out;
}

const round = (x) => Math.round(x * 10) / 10;

// Istanbul / nyc coverage JSON parsing and per-method attribution.
//
// The Istanbul JSON structure is:
//   { "/abs/path.js": { statementMap: {id: {start:{line,col}, end:{line,col}}},
//                       s: {id: hitCount}, ... } }
// Coverage attribution: for each statement whose [start.line, end.line]
// intersects the method's [startLine, endLine], count it. covered = statements
// with s[id] > 0, total = intersecting statements. Result is covered/total, or
// null when no statements intersect.

import { readFileSync, realpathSync } from 'node:fs';
import path from 'node:path';

/**
 * Load an Istanbul coverage JSON file and return a map keyed by project-relative
 * file path. Entries outside the project root are ignored.
 *
 * @param {string} filePath     Absolute or relative path to coverage-final.json.
 * @param {string} projectRoot  Absolute project root used to relativise keys.
 * @returns {Map<string, object>}
 */
export function loadCoverage(filePath, projectRoot) {
  const raw = JSON.parse(readFileSync(filePath, 'utf8'));
  const canonicalRoot = realpathOrSelf(projectRoot);
  const map = new Map();
  const exact = new Set();
  for (const [absPath, data] of Object.entries(raw)) {
    const direct = toProjectRelative(absPath, projectRoot);
    if (direct !== null) {
      map.set(direct, data);
      exact.add(direct);
      continue;
    }
    // An aliased key must never displace one that already matched literally:
    // the two spellings can name the same file with different hit counts, and
    // the literal one is what the analyzer will ask for.
    for (const aliased of throughCanonicalRoot(absPath, canonicalRoot)) {
      if (!exact.has(aliased)) map.set(aliased, data);
    }
  }
  return map;
}

/**
 * Project-relative form of `absPath`, or null when it lies outside the root.
 * Purely lexical — no filesystem access, so the caller's spelling survives.
 */
function toProjectRelative(absPath, root) {
  const rel = path.relative(root, absPath);
  if (rel.startsWith('..') || path.isAbsolute(rel)) return null;
  return rel.split(path.sep).join('/');
}

/**
 * Every project-relative spelling of a key whose root is written differently
 * from the one in hand; empty when no ancestor of the key is the project root.
 *
 * Coverage keys are absolute paths written by whatever ran the tests, and they
 * need not spell the root the way `process.cwd()` does: a checkout reached
 * through a symlink resolves to a different prefix for the same file, which is
 * the ordinary case on macOS, where the temporary directory is reached through
 * /var and reported as /private/var. Left unmatched, every entry looks
 * external, the map comes back empty, and — because a report of all N/A is
 * defined to have a maximum of 0.0 — the gate exits 0 precisely when its input
 * was misaligned.
 *
 * Only the root prefix is canonicalised. Ancestors are resolved one level at a
 * time, and everything below a matching ancestor keeps the spelling it was
 * given: resolving further would rewrite a symlinked source file, or a
 * symlinked directory above it, to its target — a path the analyzer, which
 * reports what it walked, never asks about.
 *
 * The walk does not stop at the first match. A directory inside the project
 * can resolve to the project root itself, and which of the resulting spellings
 * the analyzer asks for depends on the path it was handed, which is not
 * knowable here. Every candidate names the same file, so all of them are
 * offered and the caller keeps whichever it needs.
 */
function throughCanonicalRoot(absPath, canonicalRoot) {
  const suffix = [path.basename(absPath)];
  const candidates = [];
  let dir = path.dirname(absPath);
  for (;;) {
    if (realpathOrSelf(dir) === canonicalRoot) candidates.push(suffix.join('/'));
    const parent = path.dirname(dir);
    if (parent === dir) return candidates; // reached the filesystem root
    suffix.unshift(path.basename(dir));
    dir = parent;
  }
}

/**
 * Resolved path, or the input when it cannot be resolved. A directory that is
 * absent from this machine (coverage produced elsewhere) is not an error: it
 * simply cannot equal the root, so the walk carries on to the next ancestor,
 * which may still match.
 */
function realpathOrSelf(p) {
  try {
    return realpathSync(p);
  } catch {
    return p;
  }
}

/**
 * Compute statement coverage for a method's line range.
 *
 * @param {object|null} fileCoverage  Per-file Istanbul data (with statementMap + s).
 * @param {number} startLine          Method start line (1-based, inclusive).
 * @param {number} endLine            Method end line (1-based, inclusive).
 * @returns {number|null}             Fraction in [0, 1], or null when no statements match.
 */
export function coverageForMethod(fileCoverage, startLine, endLine) {
  if (!fileCoverage || !fileCoverage.statementMap) return null;
  const hits = fileCoverage.s || {};
  const ids = intersectingStatements(fileCoverage.statementMap, startLine, endLine);
  if (ids.length === 0) return null;
  const covered = ids.filter((id) => hits[id] > 0).length;
  return covered / ids.length;

// Cyclomatic + cognitive complexity and method extraction for
// JavaScript/JSX/Flow/TS source.
//
// Uses @babel/parser (plugins routed by file extension — flow and typescript
// cannot be enabled together) to parse, then walks the AST to find every
// function-like entry (FunctionDeclaration, class ClassMethod, assigned
// FunctionExpression or ArrowFunctionExpression) and computes its complexity
// (cyclomatic by default, or cognitive — SonarSource v1.2 — via `metric`).
//
// Cyclomatic counting rules (base 1, +1 each): IfStatement, ForStatement,
// ForInStatement, ForOfStatement, WhileStatement, DoWhileStatement,
// CatchClause, SwitchCase (including `default`), ConditionalExpression, and
// LogicalExpression (`&&`, `||`).
//
// Lambda/arrow bodies count TOWARDS the enclosing function (we descend into
// them when computing the parent's complexity). Nested NAMED
// FunctionDeclarations are skipped — they are reported as their own entries.

import { parse } from '@babel/parser';

const COMPLEXITY_TYPES = new Set([
  'IfStatement',
  'ForStatement',
  'ForInStatement',
  'ForOfStatement',
  'WhileStatement',
  'DoWhileStatement',
  'CatchClause',
  'SwitchCase',
  'ConditionalExpression',
]);

const LOGICAL_OPS = new Set(['&&', '||']);

const FUNCTION_LIKE = new Set(['FunctionExpression', 'ArrowFunctionExpression']);

// Babel attaches extra keys the generic traversal should not descend into
// (comment arrays, raw-source `extra`, `directives`, byte offsets). acorn's
// `range`/`sourceType` are kept for safety even though acorn is no longer used.
// Exported: the duplicates gate's Type-2 normalizer walks AST subtrees with
// the same exclusions when collecting function-local scopes.
export const SKIP_KEYS = new Set([
  'type', 'loc', 'range', 'sourceType', 'start', 'end',
  'leadingComments', 'trailingComments', 'innerComments', 'extra', 'directives',
]);

// Shared by both plugin routes; only the type-syntax plugin differs because
// @babel/parser refuses to combine flow and typescript. decorators-legacy
// plus decoratorAutoAccessors cover stage-3 decorator syntax (`accessor`
// fields included).
const COMMON_PLUGINS = [
  'jsx', 'decorators-legacy', 'decoratorAutoAccessors', 'classProperties',
  'classPrivateProperties', 'classPrivateMethods', 'objectRestSpread',
  'optionalChaining', 'nullishCoalescingOperator', 'dynamicImport',
  'exportDefaultFrom', 'asyncGenerators', 'topLevelAwait',
];
const FLOW_PLUGINS = [...COMMON_PLUGINS, 'flow'];
const TS_PLUGINS = [...COMMON_PLUGINS, 'typescript'];
const TS_EXTS = new Set(['.ts', '.tsx']);

/**
 * Parse source and return every method/function entry with its complexity.
 *
 * @param {string} source  JavaScript/JSX/Flow/TypeScript source code.
