                createScm: function() { return scm || {}; }
            },
            './common/githubHelpers.js': ghStub
        }),
        mocks || {}
    );
}

function makeWriteTracker() {
    var writes = [];
    return {
        writes: writes,
        file_write: function(opts) { writes.push(opts); },
        find: function(path) {
            for (var i = 0; i < writes.length; i++) {
                if (writes[i].path === path) return writes[i];
            }
            return null;
        }
    };
}

